values
  ('AM', 'AM-P-20', 'ԱԱՀ 20 % — ձեռքբերում Հայաստանի Հանրապետությունում (գնում)', '{"en":"VAT 20% — acquisition in Armenia (purchase)"}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2018-01-01', null, 'Հարկային օրենսգիրք, հոդված 71, 1-ին մաս, 1-ին կետ — հաշվանցվում (պակասեցվում) են հարկային հաշիվներում առանձնացված ԱԱՀ-ի գումարները՝ ստացողի կողմից էլեկտրոնային ստորագրությամբ հաստատված լինելու պայմանով (հոդված 68)։ Միասնական հաշվարկ, կետ 18 (և կետ 19.1՝ ճշգրտող հարկային հաշիվ)։', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('AM', 'AM-P-IMPORT', 'ԱԱՀ 20 % — ապրանքների ներմուծում (գնում)', '{"en":"VAT 20% — import of goods (purchase)"}'::jsonb, null, 'percent', 20, 'purchase', 'import', date '2018-01-01', null, 'Հարկային օրենսգիրք, հոդված 71, 1-ին մաս, 2-րդ և 3-րդ կետեր — «Բաց թողնում՝ ներքին սպառման համար» մաքսային ընթացակարգով ներմուծված ապրանքների և ԵՏՄ անդամ պետություններից ներմուծված ԵՏՄ ապրանքների համար վճարված ԱԱՀ-ի գումարները հաշվանցվում են։ Միասնական հաշվարկ, կետ 17։', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('AM', 'AM-S-0-EXPORT', 'ԱԱՀ 0 % — ապրանքի արտահանում (վաճառք)', '{"en":"VAT 0% — export of goods (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2018-01-01', null, 'Հարկային օրենսգիրք, հոդված 65, 2-րդ մաս, 1-ին և 2-րդ կետեր — «Արտահանում» մաքսային ընթացակարգով արտահանված ապրանքի, ինչպես նաև ԵՏՄ անդամ պետություն արտահանված ԵՏՄ ապրանքի մատակարարումը հարկվում է 0 տոկոս դրույքաչափով։ Միասնական հաշվարկ, կետ 12։', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('AM', 'AM-S-0-SERVICES', 'ԱԱՀ 0 % — միջազգային փոխադրումներ և Հայաստանից դուրս մատուցվող ծառայություններ (վաճառք)', '{"en":"VAT 0% — international transport and services supplied outside Armenia (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2018-01-01', null, 'Հարկային օրենսգիրք, հոդված 65, 2-րդ մաս, 4-րդ և 11-րդ կետեր — բեռների, փոստի և ուղևորների միջազգային փոխադրման ծառայություններ, ինչպես նաև աշխատանքներ և ծառայություններ, որոնց կատարման վայրը 38-րդ հոդվածի համաձայն Հայաստանի Հանրապետությունը չէ։ Միասնական հաշվարկ, կետ 12։', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('AM', 'AM-S-20', 'ԱԱՀ 20 % — մատակարարում Հայաստանի Հանրապետությունում (վաճառք)', '{"en":"VAT 20% — supply in Armenia (sale)"}'::jsonb, null, 'percent', 20, 'sale', 'domestic', date '2018-01-01', null, 'Հարկային օրենսգիրք, հոդված 63, 1-ին մաս — ԱԱՀ-ն հաշվարկվում է 20 տոկոս դրույքաչափով, բացառությամբ 64-րդ և 65-րդ հոդվածներով սահմանված գործարքների։ Միասնական հաշվարկ, կետ 7 (դեպի ավելացում) և կետ 8.1 (ճշգրտող հարկային հաշիվ՝ նվազեցում)։', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null),
  ('AM', 'AM-S-EXEMPT', 'ԱԱՀ-ից ազատված գործարք (վաճառք)', '{"en":"VAT-exempt transaction (sale)"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2018-01-01', null, 'Հարկային օրենսգիրք, հոդված 64, 2-րդ մաս — ԱԱՀ-ից ազատվում են, ի թիվս այլոց, կրթական ծառայությունները (1-ին կետ), բժշկական օգնությունը և առողջապահական ծառայությունները (11-րդ կետ), ապահովագրական ծառայությունները (44-րդ կետ) և բանկային ու այլ ֆինանսական գործառնությունները (47-րդ կետ)։ Ձեռք բերվածի նկատմամբ ԱԱՀ-ի հաշվանցում չի կատարվում (հոդված 72, 1-ին մաս, 2-րդ կետ)։ Միասնական հաշվարկ, կետ 13։', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'tax-code', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

insert into tax_posting_templates
  (tax_template_id, document_kind, posting_type, factor_percent, account_code,
   declaration_box, declaration_boxes, box_factor_percent, report_code, sequence)
select t.id,
       v.document_kind::tax_document_kind,
       v.posting_type::tax_posting_type,
       v.factor_percent::numeric,
       v.account_code::text,
       v.declaration_box::text,
       v.declaration_boxes::text[],
       v.box_factor_percent::numeric,
       v.report_code::text,
       v.sequence::integer
  from (values
    ('AM-P-20', 'invoice', 'base', 100, null, '18A', array['18A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-P-20', 'invoice', 'tax', 100, '2261', '18B', array['18B']::text[], 100, 'AM-VAT-MONTHLY', 20),
    ('AM-P-20', 'credit_note', 'base', 100, null, '191A', array['191A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-P-20', 'credit_note', 'tax', 100, '2261', '191B', array['191B']::text[], 100, 'AM-VAT-MONTHLY', 20),
    ('AM-P-IMPORT', 'invoice', 'base', 100, null, '17A', array['17A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-P-IMPORT', 'invoice', 'tax', 100, '2262', '17B', array['17B']::text[], 100, 'AM-VAT-MONTHLY', 20),
    ('AM-P-IMPORT', 'credit_note', 'base', 100, null, '17A', array['17A']::text[], -100, 'AM-VAT-MONTHLY', 10),
    ('AM-P-IMPORT', 'credit_note', 'tax', 100, '2262', '17B', array['17B']::text[], -100, 'AM-VAT-MONTHLY', 20),
    ('AM-S-0-EXPORT', 'invoice', 'base', 100, null, '12A', array['12A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-0-EXPORT', 'credit_note', 'base', 100, null, '12A', array['12A']::text[], -100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-0-SERVICES', 'invoice', 'base', 100, null, '12A', array['12A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-0-SERVICES', 'credit_note', 'base', 100, null, '12A', array['12A']::text[], -100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-20', 'invoice', 'base', 100, null, '7A', array['7A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-20', 'invoice', 'tax', 100, '52431', '7B', array['7B']::text[], 100, 'AM-VAT-MONTHLY', 20),
    ('AM-S-20', 'credit_note', 'base', 100, null, '81A', array['81A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-20', 'credit_note', 'tax', 100, '52431', '81B', array['81B']::text[], 100, 'AM-VAT-MONTHLY', 20),
    ('AM-S-EXEMPT', 'invoice', 'base', 100, null, '13A', array['13A']::text[], 100, 'AM-VAT-MONTHLY', 10),
    ('AM-S-EXEMPT', 'credit_note', 'base', 100, null, '13A', array['13A']::text[], -100, 'AM-VAT-MONTHLY', 10)
  ) as v (tax_code, document_kind, posting_type, factor_percent, account_code,
          declaration_box, declaration_boxes, box_factor_percent, report_code, sequence)
  join tax_templates t on t.country = 'AM' and t.code = v.tax_code
on conflict (tax_template_id, document_kind, posting_type, sequence) do update set
  factor_percent     = excluded.factor_percent,
  account_code       = excluded.account_code,
  declaration_box    = excluded.declaration_box,
  declaration_boxes  = excluded.declaration_boxes,
  box_factor_percent = excluded.box_factor_percent,
  report_code        = excluded.report_code;

insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format,
   rounding_unit, rounding_reference, rounding_source_key)
values
  ('AM', 'AM-VAT-MONTHLY', 'Ավելացված արժեքի հարկի և ակցիզային հարկի միասնական հաշվարկ (բաժին 1՝ ԱԱՀ)', array['month']::declaration_period[], 'month'::declaration_period, date '2018-01-01', null, 'ՀՀ կառավարությանն առընթեր պետական եկամուտների կոմիտեի նախագահի 2016 թվականի դեկտեմբերի 30-ի N 298-Ն հրամանի հավելված (ձև, տեղակայված 30.01.2023 N 76-Ն փոփոխությամբ)․ Հարկային օրենսգիրք, հոդված 69, 1-ին մաս — հաշվետու ժամանակաշրջանը օրացուցային ամիսն է։ Բաժին 2-ը (ակցիզային հարկ) այս փաթեթում չի ներառված։', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Հարկային օրենսգիրք, հոդված 75, 1-ին մաս — ԱԱՀ վճարողները միասնական հաշվարկը ներկայացնում են հաշվետու ժամանակաշրջանին հաջորդող ամսվա 20-ը ներառյալ։', 'tax-code', null, 1, 'N 298-Ն հրամանի հավելված, լրացման կարգի 4-րդ կետ — արժեքային մեծությունները լրացվում են դրամներով՝ առանց լումաների։', 'vat-return-form')
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  rounding_unit       = excluded.rounding_unit,
  rounding_reference  = excluded.rounding_reference,
  rounding_source_key = excluded.rounding_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('AM', 'AM-VAT-MONTHLY', '7A', 'base', 'Հարկման բազա — ԱԱՀ-ի 20 % դրույքաչափով հարկվող գործարքներ', '{"en":"Tax base — transactions taxed at the 20% VAT rate (line 7, box A)"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 7, վանդակ [Ա]։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '7B', 'tax', 'ԱԱՀ կրեդիտ — ԱԱՀ-ի 20 % դրույքաչափով հարկվող գործարքների գծով հաշվարկված ԱԱՀ', '{"en":"VAT credit — VAT calculated on transactions taxed at 20% (line 7, box B)"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 7, վանդակ [Բ]։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '81A', 'base', 'Ճշգրտող հարկային հաշիվներով գործարքների հարկման բազա՝ նվազեցում', '{"en":"Tax base of transactions on adjusting tax invoices — reduction (line 8.1, box A)"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 8, ենթակետ 1, վանդակ [Ա]։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '81B', 'tax', 'Ճշգրտող հարկային հաշիվներով գործարքների ԱԱՀ՝ նվազեցում', '{"en":"VAT on transactions on adjusting tax invoices — reduction (line 8.1, box B)"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 8, ենթակետ 1, վանդակ [Բ]։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '12A', 'base', 'Հարկման բազա — ԱԱՀ-ի 0-ական դրույքաչափով հարկվող գործարքներ', '{"en":"Tax base — transactions taxed at the 0% VAT rate (line 12, box A)"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 12, վանդակ [Ա]․ Հարկային օրենսգիրք, հոդված 65։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '13A', 'base', 'Հարկման բազա — ԱԱՀ-ից ազատված գործարքներ', '{"en":"Tax base — VAT-exempt transactions (line 13, box A)"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 13, վանդակ [Ա]․ Հարկային օրենսգիրք, հոդված 64։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '16A', 'total', 'Ընդամենը ԱԱՀ-ի կրեդիտ — հարկման բազա', '{"en":"Total VAT credit — tax base (line 16, box A)"}'::jsonb, 70, null, array['7A', '12A', '13A']::text[], array['81A']::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 16, վանդակ [Ա] (այս փաթեթը կիրառում է միայն 7, 8.1, 12 և 13 կետերը)։', 'vat-return-form'),
  ('AM', 'AM-VAT-MONTHLY', '16B', 'total', 'Ընդամենը ԱԱՀ-ի կրեդիտ — հաշվարկված ԱԱՀ', '{"en":"Total VAT credit — VAT calculated (line 16, box B)"}'::jsonb, 80, null, array['7B']::text[], array['81B']::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 16, վանդակ [Բ] (այս փաթեթը կիրառում է միայն 7 և 8.1 կետերը)։', 'vat-return-form'),
