  ('AM', 'AM-VAT-MONTHLY', '191B', 'tax', 'Ձեռքբերումներին վերաբերող ճշգրտող հարկային հաշիվներ՝ նվազեցում (ԱԱՀ դեբետ)', '{"en":"Adjusting tax invoices on acquisitions — reduction (VAT debit) (line 19.1, box B)"}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Միասնական հաշվարկ, բաժին 1, կետ 19, ենթակետ 1, վանդակ [Բ]։', 'vat-return-form'),
