insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('AM-BS', 'AM', 'default', 'Ֆինանսական վիճակի մասին հաշվետվություն (ծանոթագրություն՝ ամփոփ)', 'balance_sheet', 'IFRS', date '1970-01-01', null, 'ՀՀ օրենք հաշվապահական հաշվառման մասին (04.12.2019) — ֆինանսական հաշվետվությունները կազմվում են ՖՀՄՍ-ների կամ փոքր և միջին կազմակերպությունների ՖՀՄՍ-ի համաձայն․ տողերը խմբավորում են 353-Ն հրամանի հաշվային պլանի դասերը (1-2՝ ակտիվներ, 3՝ կապիտալ, 4-5՝ պարտավորություններ, 6-7՝ եկամուտներ և ծախսեր)։ Տողերի կառուցվածքը փաթեթի ամփոփ ներկայացումն է, ոչ թե օրենքով հաստատված ձև։', 'accounting-law'),
  ('AM-IS', 'AM', 'default', 'Շահույթի կամ վնասի մասին հաշվետվություն (ծանոթագրություն՝ ամփոփ)', 'income_statement', 'IFRS', date '1970-01-01', null, 'ՀՀ օրենք հաշվապահական հաշվառման մասին (04.12.2019) — ֆինանսական հաշվետվությունները կազմվում են ՖՀՄՍ-ների կամ փոքր և միջին կազմակերպությունների ՖՀՄՍ-ի համաձայն․ տողերը խմբավորում են 353-Ն հրամանի հաշվային պլանի դասերը (1-2՝ ակտիվներ, 3՝ կապիտալ, 4-5՝ պարտավորություններ, 6-7՝ եկամուտներ և ծախսեր)։ Տողերի կառուցվածքը փաթեթի ամփոփ ներկայացումն է, ոչ թե օրենքով հաստատված ձև։', 'accounting-law')
