update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{NNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Հարկային օրենսգիրք, հոդված 56 — հաշվարկային փաստաթղթերը (այդ թվում՝ հարկային հաշիվները) դուրս են գրվում էլեկտրոնային եղանակով պետական եկամուտների կոմիտեի էլեկտրոնային հաշվարկային փաստաթղթերի համակարգում, որտեղ էլ տրվում է փաստաթղթի համարը․ առևտրային փաստաթղթի սեփական համարակալման պարտադիր ձևաչափ օրենքով սահմանված չէ, այստեղ բերված հաջորդական համարակալումը օրինակ է։',
  numbering_source_key          = 'tax-code',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Հարկային օրենսգիրք, հոդված 56, 4-րդ մաս — հաշվարկային փաստաթուղթը դուրս է գրվում ապրանքի մատակարարման, աշխատանքի կատարման կամ ծառայության մատուցման ավարտի պահին (օրենսգրքի 8-րդ և 8.1-ին մասերով նախատեսված դեպքերում՝ նախապես)․ փաթեթը մոտարկում է կանոնը `invoice_if_issued` արժեքով (տե՛ս README.md)։',
  tax_point_source_key          = 'tax-code',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Հարկային օրենսգիրք, հոդված 56, 10-13-րդ մասեր — հաշվարկային փաստաթուղթը չեղյալ է հայտարարվում կամ ուղղվում է ճշգրտող հաշվարկային փաստաթղթով՝ առանց սկզբնական գրառումը ջնջելու։',
  posted_edit_policy_source_key = 'tax-code',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Հարկային օրենսգիրք, հոդված 56, 3-րդ մաս — հաշվարկային փաստաթղթերը դուրս են գրվում էլեկտրոնային ձևով (բացառություն՝ ՀԴՄ կտրոնը և Կառավարության սահմանած դեպքերը)․ հոդված 68 — ԱԱՀ վճարողները էլեկտրոնային ստորագրությամբ հաստատում են մատակարարների դուրս գրած հարկային հաշիվները։ Համակարգը պետական եկամուտների կոմիտեի էլեկտրոնային հաշվարկային փաստաթղթերի համակարգն է (file-online.taxservice.am), այլ ոչ թե EN 16931 / Peppol մոդելը, ուստի `profile`, `party_scheme` և `vat_scheme` դատարկ են, իսկ `obligation` և `mandatory_from` չեն լրացվում․ ձևաչափը պարտադիրություն է հայտարարում միայն այն դեպքում, երբ պրոֆիլն ասում է, թե ինչն է պարտադիր (տե՛ս README.md և docs/international.md, «From Armenia»)։',
  einvoice_source_key           = 'tax-code',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_account_scheme           = 'iban',
  bank_statement_formats        = array['csv']::text[],
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'AM';
